      ]
    }
  ]
}$j$),

('ea-sports-fc-24', $j${
  "intro": "EA Sports FC 24 اولین بازی فوتبال EA بعد از جدایی از نام FIFA است؛ نقطه شروع دوره‌ای تازه برای پرطرفدارترین سری فوتبال جهان. بازی با مجوز لیگ‌های بزرگی مثل لیگ برتر انگلیس، لالیگا، بوندس‌لیگا، سری آ و لیگ قهرمانان اروپا، همراه با لیگ‌های فوتبال زنان، همان حس آشنا را با موتور Frostbite و انیمیشن‌های به‌روزتر ارائه می‌کند.",
