        "داستان پر از شخصیت‌های به‌یادماندنی و مأموریت‌های فرعی است که بسیاری از آن‌ها به اندازه خط اصلی عمیق و احساسی‌اند. تصمیم‌های شما هم بر رابطه‌ها و پایان ماجرا اثر می‌گذارند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
