        "کمپین برخلاف بیشتر نسخه‌های سری، تصمیم‌هایی دارد که روی مسیر داستان و پایان آن اثر می‌گذارند و مأموریت‌های جانبی با جمع‌آوری مدارک قابل انجام‌اند."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "چندنفره و زامبی",
      "paragraphs": [
        "بخش چندنفره با نقشه‌های متنوع، حالت‌های کلاسیک و حالت‌های بزرگ‌تر با خودرو، همان ریتم سریع Call of Duty را دارد. سیستم ساخت کلاس و ارتقای سلاح هم انگیزه زیادی برای ادامه بازی می‌دهد.",
        "حالت زامبی‌ها هم با داستان خودش برگشته و چهار بازیکن باید در برابر موج‌های بی‌پایان مردگان مقاومت کنند، سلاح ارتقا دهند و رازهای نقشه را کشف کنند. حالت دونفره روی یک صفحه هم در برخی بخش‌ها پشتیبانی می‌شود."
