      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر فقط کمپین را می‌خواهید، اکانت ظرفیت ۱ ارزان‌ترین راه است، به شرط این‌که کنسول آفلاین بماند. اما برای چندنفره و زامبی آنلاین، که جذاب‌ترین بخش بازی‌اند، ظرفیت ۱ مناسب نیست و باید ظرفیت ۲ یا ۳ را انتخاب کنید؛ بازی آنلاین روی PS5 هم به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
