('seeker-my-shadow', $j${
  "intro": "Seeker: My Shadow یک ماجرای معمایی واقعیت مجازی از استودیو Jestercraft است که برای هدست PlayStation VR2 عرضه شده است. در این بازی شما نقش روحی غول‌پیکر را دارید که به موجودی کوچک و دوست‌داشتنی به نام کیپو کمک می‌کند از مراحل پر از معما عبور کند. توجه کنید که این بازی بدون هدست PS VR2 قابل اجرا نیست.",
