('nier-automata', $j${
  "intro": "NieR: Automata یک نقش‌آفرینی اکشن از Square Enix و استودیو PlatinumGames است که با کارگردانی یوکو تارو، به یکی از متفکرانه‌ترین و احساسی‌ترین بازی‌های دهه گذشته تبدیل شد. بازی مبارزات سریع و زیبای PlatinumGames را با داستانی فلسفی درباره هویت، معنا و انسانیت ترکیب می‌کند.",
