('battle-of-rebels', $j${
  "intro": "Battle of Rebels یک شوتر مستقل با امکان بازی اول‌شخص و سوم‌شخص است که در آن باید در برابر موج‌های زامبی‌ها مقاومت کنید. بازی را می‌توان تنها یا به صورت چندنفره و میان‌پلتفرمی تجربه کرد و برنده یک رقابت بازی‌سازی با موتور Unreal در فلوریدا هم بوده است.",
  "suits": ["علاقه‌مندان شوترهای زامبی", "بازی همکاری با دوستان", "بازیکنانی که اکشن ساده و سریع می‌خواهند"],
  "sections": [
    {
      "heading": "داستان و گیم‌پلی",
      "paragraphs": [
        "بیگانگان دستگاه‌های شبیه‌سازی انسان را در مرکز شهر کار گذاشته‌اند؛ دستگاه‌هایی که DNA انسان را آلوده می‌کنند و مردم را به زامبی تبدیل می‌کنند. مأموریت شما از کار انداختن این دستگاه‌هاست، اما پیش از آن باید منطقه را از زامبی‌ها پاک کنید.",
        "هسته بازی تیراندازی در برابر موج‌های پیاپی دشمنان است و انتخاب نمای اول‌شخص یا سوم‌شخص با شماست."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "Battle of Rebels تولید کوچکی است و بیشتر برای کسانی مناسب است که دنبال یک شوتر زامبی سبک و ارزان برای بازی کوتاه یا با دوستان هستند."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر تنها بازی می‌کنید، اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول آفلاین بماند. برای بازی چندنفره آنلاین ظرفیت ۲ یا ۳ لازم است و بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('firefighting-simulator-the-squad', $j${
  "intro": "Firefighting Simulator: The Squad یک شبیه‌ساز آتش‌نشانی از ناشر astragon Entertainment است که شما را به عضویت گروه آتش‌نشانی یک شهر بزرگ آمریکایی درمی‌آورد. آژیر خودرو را روشن می‌کنید، شلنگ را برمی‌دارید و با آتش‌سوزی‌هایی واقع‌گرایانه مقابله می‌کنید تا جان مردم را نجات دهید.",
  "suits": ["علاقه‌مندان شبیه‌سازی", "بازی همکاری با دوستان", "کسانی که به آتش‌نشانی علاقه دارند"],
  "sections": [
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "بیش از ۴۰ محل مأموریت در شهری الهام‌گرفته از سواحل غربی آمریکای شمالی وجود دارد؛ از خانه‌های مسکونی تا ساختمان‌های تجاری. هر آتش‌سوزی رفتار متفاوتی دارد و باید نوع آتش، مسیر گسترش و افراد گرفتار را در نظر بگیرید.",
        "تجهیزات واقعی آتش‌نشانی، از کلاه و چکمه تا دستگاه تنفس، در اختیارتان است و استفاده درست از شلنگ، تبر و ابزارهای دیگر، کلید موفقیت در هر مأموریت است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "تنها یا با دوستان",
      "paragraphs": [
        "می‌توانید گروه خود را با هم‌تیمی‌های کنترل‌شده توسط هوش مصنوعی هدایت کنید یا با دوستانتان به‌صورت آنلاین، به‌عنوان یک تیم آتش‌نشانی واقعی، مأموریت‌ها را انجام دهید."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "اگر تنها بازی می‌کنید، اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول آفلاین بماند. برای همکاری آنلاین ظرفیت ۲ یا ۳ لازم است و بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('worms-rumble-fully-loaded-edition', $j${
  "intro": "Worms Rumble نخستین بازی سری Worms است که به‌جای نبرد نوبتی، مبارزه در زمان واقعی دارد. کرم‌های مسلح و بامزه این بار در نبردهای ۳۲ نفره بتل رویال و دث‌مچ، با پشتیبانی کامل از بازی میان‌پلتفرمی، به جان هم می‌افتند. نسخه Fully Loaded محتوای اضافه منتشرشده برای بازی را هم شامل می‌شود.",
  "suits": ["طرفداران Worms", "بازیکنان آنلاین", "کسانی که بازی سریع و خنده‌دار می‌خواهند"],
  "sections": [
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "سلاح‌های آشنا و عجیب سری Worms، از بازوکا و نارنجک تا گوسفند انفجاری، این بار در جریان مسابقه‌ای سریع و دوبعدی استفاده می‌شوند. باید در نقشه حرکت کنید، سلاح جمع کنید و آخرین کرم زنده بمانید.",
        "ریتم بازی سریع و پرهرج‌ومرج است و هر مسابقه چند دقیقه بیشتر طول نمی‌کشد."
      ]
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Worms Rumble فقط آنلاین است و بخش آفلاین واقعی ندارد، پس اکانت ظرفیت ۱ برای آن مناسب نیست. ظرفیت ۳ ارزان‌ترین راه برای بازی آنلاین است و ظرفیت ۲ انعطاف بیشتری دارد. بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('poppy-playtime-chapter-4-safe-haven', $j${
  "intro": "Poppy Playtime Chapter 4: Safe Haven چهارمین فصل از سری وحشت معمایی Poppy Playtime از استودیو Mob Entertainment است و به گفته سازندگان، تاریک‌ترین فصل این ماجرا تا امروز. شما به اعماقی از کارخانه اسباب‌بازی‌سازی Playtime Co. رانده می‌شوید که بسیار پایین‌تر از هر چیزی است که دنیا از آن خبر داشت.",
  "suits": ["طرفداران Poppy Playtime", "نوجوانان علاقه‌مند به وحشت", "علاقه‌مندان معما"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "در این فصل با تهدیدهای تازه و ترسناک و ساخته‌های غیرطبیعی کارخانه روبه‌رو می‌شوید و افشاگری‌هایی تکان‌دهنده درباره آزمایش‌های پنهان Playtime Co. پیش رویتان قرار می‌گیرد. «پناهگاه امن»، همان‌طور که از نامش پیداست، نقش مهمی در این بخش از داستان دارد.",
        "برای فهم کامل ماجرا، بهتر است فصل‌های قبلی را پیش از این فصل تجربه کرده باشید."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مثل فصل‌های قبل، ابزار اصلی شما «گرب‌پک» است؛ کوله‌ای با دو دست کشسان که با آن اشیا را از دور می‌گیرید، مدارهای برق را وصل می‌کنید و از روی شکاف‌ها تاب می‌خورید. معماهای محیطی و بخش‌های تعقیب‌وگریز با هیولاهای اسباب‌بازی، ستون اصلی تجربه‌اند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این فصل تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. هر فصل Poppy Playtime جداگانه فروخته می‌شود؛ قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('poppy-playtime-chapter-2-fly-in-a-web', $j${
  "intro": "Poppy Playtime Chapter 2: Fly in a Web فصل دوم سری وحشت معمایی Poppy Playtime از Mob Entertainment است. این فصل سه برابر بزرگ‌تر از فصل اول است و شما را عمیق‌تر به درون کارخانه اسباب‌بازی‌سازی متروکه می‌برد؛ جایی که معماهای پیچیده‌تر و اسباب‌بازی‌های هولناک‌تری منتظرتان هستند.",
