      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این فصل تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. هر فصل جداگانه فروخته می‌شود؛ قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('poppy-playtime', $j${
  "intro": "Poppy Playtime فصل نخست سری وحشت معمایی پرطرفدار Mob Entertainment است؛ بازی‌ای که با شخصیت ترسناک «هاگی واگی» در اینترنت به شهرت رسید. شما باید در کارخانه اسباب‌بازی‌سازی متروکه‌ای زنده بمانید که اسباب‌بازی‌های انتقام‌جو در آن منتظرتان هستند.",
  "suits": ["نوجوانان علاقه‌مند به وحشت", "علاقه‌مندان معما", "بازیکنانی که بازی کوتاه می‌خواهند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شرکت Playtime Co. زمانی پادشاه صنعت اسباب‌بازی بود، تا این‌که یک روز همه کارکنان کارخانه بدون هیچ ردی ناپدید شدند. سال‌ها بعد، شما برای کشف حقیقت به این کارخانه متروکه بازمی‌گردید.",
        "ترکیب رنگ‌های شاد و طراحی کودکانه با ترس و تعقیب، حال‌وهوای خاص این بازی را ساخته است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "ابزار اصلی شما «گرب‌پک» است؛ کوله‌ای با دستان کشسان که با آن می‌توانید اشیا را از دور بگیرید و مدارهای برقی را به هم وصل کنید تا درها و ماشین‌آلات کار کنند. معماهای محیطی بخش بزرگی از بازی‌اند و در لحظه‌های پایانی، تعقیب‌وگریزی نفس‌گیر در انتظارتان است. این فصل کوتاه است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این بازی تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('little-nightmares-ii-enhanced-edition', $j${
  "intro": "Little Nightmares II Enhanced Edition نسخه بهینه‌شده Little Nightmares II برای PS5 است؛ پلتفرمر معمایی ترسناک استودیو سوئدی Tarsier Studios. این نسخه با بهبودهای گرافیکی و صوتی، دنیای کابوس‌وار بازی را با جزئیات بیشتری به نمایش می‌گذارد.",
  "suits": ["طرفداران وحشت فضاسازی‌شده", "علاقه‌مندان پلتفرمر معمایی", "بازیکنانی که داستان بی‌کلام دوست دارند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "مونو، پسری که کیسه‌ای کاغذی روی سر دارد، در جنگلی تاریک بیدار می‌شود. او همراه سیکس، دختری با بارانی زرد که در نسخه اول قهرمان بود، به شهری پوسیده سفر می‌کند که سیگنال برجی دوردست آن را دگرگون کرده است. این بازی پیش‌درآمد نسخه اول است.",
        "مثل نسخه اول، داستان هیچ دیالوگی ندارد و همه‌چیز با تصاویر، صدا و محیط روایت می‌شود. پایان بازی از تأثیرگذارترین لحظه‌های سری است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "باید پنهان شوید، فرار کنید و معماهای محیطی را حل کنید. سیکس با هوش مصنوعی کنترل می‌شود و در بسیاری از معماها به کمک او نیاز دارید. این بار مونو می‌تواند اشیایی مثل چکش یا لوله را بردارد و از خود دفاع کند، هرچند این اشیا سنگین و کندند. ساکنان هولناک شهر، از معلم مدرسه تا بیماران بیمارستان، هر کدام بخشی به‌یادماندنی از بازی را می‌سازند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این بازی کاملاً تک‌نفره است، پس اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید کنسولتان آنلاین باشد، ظرفیت ۲ انعطاف بیشتری دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('tom-clancys-rainbow-six-siege-x-elite-edition', $j${
  "intro": "Rainbow Six Siege X بزرگ‌ترین تحول در تاریخ شوتر تاکتیکی تیمی Ubisoft است؛ بازی‌ای که سال‌هاست مرجع سبک شوترهای تاکتیکی رقابتی به حساب می‌آید. نسخه Elite Edition دسترسی به همه حالت‌های بازی، از جمله مسابقات رتبه‌بندی‌شده و Siege Cup، و ۱۶ اپراتور اضافه را فراهم می‌کند.",
  "suits": ["بازیکنان رقابتی آنلاین", "طرفداران شوترهای تاکتیکی", "بازی تیمی با دوستان"],
  "sections": [
    {
      "heading": "ایده اصلی بازی",
      "paragraphs": [
        "در هر دور، یک تیم پنج‌نفره مهاجم و یک تیم پنج‌نفره مدافع است. مدافعان محل هدف را با دیوارهای تقویت‌شده، تله‌ها و ابزارها مستحکم می‌کنند و مهاجمان با پهپادهای شناسایی، مواد منفجره و ابزارهای ویژه برای نفوذ برنامه‌ریزی می‌کنند. تقریباً هر دیوار و کف قابل‌تخریب است و این، مسیرهای حمله و دفاع را بی‌شمار می‌کند.",
        "اپراتورها هر کدام ابزار و نقش منحصربه‌فردی دارند و ترکیب درست تیم و ارتباط میان بازیکنان، اغلب از مهارت تیراندازی مهم‌تر است."
      ],
      "media": "screenshot:1"
    },
    {
      "heading": "Siege X چه تغییری داد؟",
      "paragraphs": [
        "Siege X همراه با بازطراحی‌های فنی، به‌روزرسانی نقشه‌ها و تغییرات در هسته تاکتیکی بازی آمد و حالت تازه‌ای هم به مجموعه حالت‌ها افزود. بازی در این دوره دسترسی پایه رایگان پیدا کرد و نسخه‌هایی مثل Elite، دسترسی کامل به حالت‌های رقابتی و اپراتورهای بیشتر را باز می‌کنند."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
