('unravel', $j${
  "intro": "Unravel یک پلتفرمر معمایی آرام و احساسی از استودیو سوئدی Coldwood Interactive و ناشر EA است. قهرمان بازی یارنی است؛ موجود کوچکی که از یک رشته کاموا ساخته شده و در سفری بزرگ در طبیعت الهام‌گرفته از شمال اسکاندیناوی، به دنبال خاطرات خانواده‌ای ازدست‌رفته می‌گردد.",
