('stranger-of-paradise-final-fantasy-origin', $j${
  "intro": "Stranger of Paradise: Final Fantasy Origin یک اکشن نقش‌آفرینی تاریک از Square Enix و استودیو Team NINJA، سازنده سری Nioh، است. بازی بازتعریفی جسورانه از نخستین Final Fantasy است که دنیای آشنای سری را با مبارزات سخت و سریع به سبک Team NINJA ترکیب می‌کند.",
