('the-dark-pictures-anthology-house-of-ashes', $j${
  "intro": "House of Ashes سومین قسمت از مجموعه The Dark Pictures Anthology استودیو Supermassive Games است؛ مجموعه‌ای از بازی‌های وحشت سینمایی مستقل که تصمیم‌های شما داستان و سرنوشت شخصیت‌ها را تعیین می‌کند. این بار ماجرا در روزهای پایانی جنگ عراق و در اعماق معبدی سومری مدفون زیر خاک می‌گذرد.",
